places": [{"name": "Chicago, United States", "role": "Exhibition site"}, {"name": "Eldon, United States", "role": "Inspiration site"}, {"name": "Iowa, United States", "role": "Cultural context"}], "texts": [{"title": "Wikipedia: American Gothic", "type": "Reference article", "slug": "american-gothic"}], "externalLinks": ["https://www.wikidata.org/wiki/Q464782", "https://en.wikipedia.org/wiki/American_Gothic"], "tags": ["painting", "Paintings & Visual Art", "cause-and-effect"], "thumbnailUrl": "", "quote": "", "legacySummary": "American Gothic contributed to the historical record of the Modern period. Key lasting impacts include: Contributed to artistic heritage and cultural identity. Their legacy is studied through the lens of historical causation.", "historicalSignificance": {"significanceScore": 7, "significanceNarrative": "American Gothic is a crucial representation of American identity during the Great Depression, influencing the Regionalism movement and resonating with themes of rural life and economic hardship.", "significanceCategory": "regional"}, "_editLog": [{"timestamp": "2026-07-01T17:21:27Z", "editorId": "gpt-4o-mini·cloud·GH#28535199546", "field": "summary", "oldValue": "1930 painting by grant wood Created by Grant Wood. Created c. 1930.", "newValue": "American Gothic, painted in 1930 by Grant Wood, stands as a quintessential symbol of American art and culture, encapsulating the ethos of the Great Depression era in the United States. Located in the Art Institute of Chicago, this iconic work depicts a stern farmer and his daughter, embodying the resilience and stoicism of rural America during a time of economic turmoil. The painting’s sharp portrayal of Midwestern American life has resonated across the globe, making it a pivotal piece in the canon of modern art. Wood's work emerged from a broader context of American Regionalism, a movement that sought to depict everyday life and the American landscape authentically, contrasting sharply with the European avant-garde movements of the time.

In the summer of 1930, Wood was inspired by the architecture of a small house in Eldon, Iowa, which features a Gothic window. This architectural element led him to create a work that is not just a portrait but a narrative infused with cultural significance. The farmer and daughter, representing traditional American values, reflect a deep-seated connection to the land, a theme that was particularly poignant amidst the agricultural struggles of the era. The painting was first exhibited at the Art Institute of Chicago, where it garnered immense acclaim, and it quickly became emblematic of American identity, influencing both artists and the general public.

The legacy of American Gothic extends beyond its immediate aesthetic impact; it has become a cultural touchstone that continues to inspire discussions around American identity, rural versus urban life, and the struggles of the working class. Its imagery has been parodied and referenced in countless media, from advertisements to television, showcasing its enduring relevance. Moreover, it has sparked dialogues about the role of art in society, particularly in times of hardship, influencing generations of artists to explore themes of realism and social commentary in their work."}, {"timestamp": "2026-07-01T17:21:27Z", "editorId": "gpt-4o-mini·cloud·GH#28535199546", "field": "detailsJson.causes", "oldValue": ["Artistic patronage and creative expression"], "newValue": ["The Great Depression prompted a search for authentic American identity in art.", "The rise of American Regionalism in the 1920s influenced Wood's artistic direction.", "The architectural features of a Gothic-style farmhouse in Iowa inspired the painting's composition."]}, {"timestamp": "2026-07-01T17:21:27Z", "editorId": "gpt-4o-mini·cloud·GH#28535199546", "field": "detailsJson.effects", "oldValue": ["Contributed to artistic heritage and cultural identity"], "newValue": ["American Gothic became a symbol of American resilience during economic hardship.", "The painting influenced the American Regionalism movement, inspiring future artists to depict rural life.", "It has been extensively referenced in popular culture, indicating its lasting impact on American art and identity."]}, {"timestamp": "2026-07-01T17:21:27Z", "editorId": "gpt-4o-mini·cloud·GH#28535199546", "field": "detailsJson.relationships", "oldValue": [{"sourceSlug": "american-gothic", "sourceName": "American Gothic", "verb": "OCCURS_DURING", "targetSlug": "era-modern", "targetName": "Modern", "context": "American Gothic is situated within the Modern (950)"}], "newValue": [{"sourceSlug": "grant-wood", "sourceName": "Grant Wood", "verb": "CREATES